/**
 * The gas bill view-model (t_6c2606d1 / UX spec t_860756c3): what the panel
 * reads out of a parsed Enbridge feed — money honesty, ¢/m³ rates, the three
 * volume numbers, and the A/B/C interval states.
 *
 * FIXTURE POLICY: SYNTHETIC only (`tests/fixtures/enbridge-gas-synthetic.xml`,
 * generated by `scripts/generate-enbridge-gas-fixture.mjs` — see
 * tests/fixtures/README.md). The real EGD export carries Mark's name, home
 * address, account number, meter serial and agreement id; it never enters the
 * repo, a fixture, or an attachment.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

import { parseGreenButtonFeed, type BillLineItem, type UsageSummary } from './energy';
import {
  enrichGasSummaries,
  gasCharges,
  gasFacts,
  gasIntervalState,
  gasMoney,
  gasRates,
  gasSupplier,
  gasVolume,
  isGasFeed,
  isGasSummary,
  isRateLine,
} from './gasBillUi';

const USAGE_XML = readFileSync(
  join(__dirname, '../../tests/fixtures/enbridge-gas-synthetic.xml'),
  'utf8',
);

const feed = parseGreenButtonFeed(USAGE_XML);
const summaries = enrichGasSummaries(feed);

/** AC6/AC7 figures — the same tables enbridgeGas.test.ts pins on the parser. */
const DUE = [175.76, 153.06, 117.35, 84.75, 65.45, 132.06, 85.37, 119.04, 93.33, 72.47];
const TOTALS = [161.89, 153.06, 117.35, 84.75, 65.45, 132.06, 80.07, 119.04, 93.33, 66.29];
/** The three periods where Amount Due ≠ Total Gas Charges (DoD 6). */
const DUE_MINUS_TOTAL = [13.87, 0, 0, 0, 0, 0, 5.3, 0, 0, 6.18];
const READ_DELTA = [427, 386, 268, 176, 112, 347, 161, 295, 206, 112];
const BILLED_VOLUME = [429, 388, 270, 177, 113, 349, 162, 297, 207, 113];
const UNADJUSTED = [
  426.569, 385.801, 268.47, 175.997, 112.36, 347.022, 161.082, 295.317, 205.827, 112.36,
];
const BLOCK_VALUES = [427, 386, 268, 174, 2];

const round2 = (n: number): number => Math.round(n * 100) / 100;

describe('recognition — this dataset is natural gas', () => {
  it('flags the feed and every one of its ten periods', () => {
    expect(summaries).toHaveLength(10);
    expect(isGasFeed(feed.summaries)).toBe(true);
    expect(summaries.every(isGasSummary)).toBe(true);
  });

  it('a usage file alone is enough: no Account Details supplier is invented', () => {
    // The synthetic fixture is the usage extract on its own — enrichment must
    // not fabricate a supplier label (DoD 1: enrichment is never required).
    expect(summaries.every((s) => gasSupplier(s) === null)).toBe(true);
  });
});

describe('money honesty — the two feed figures and their difference (DoD 2/6)', () => {
  it('reads Amount Due and Total Gas Charges off their own lines, all ten', () => {
    summaries.forEach((s, i) => {
      const m = gasMoney(s);
      expect(m.amountDue).toBe(DUE[i]);
      expect(m.total).toBe(TOTALS[i]);
    });
  });

  it('the difference is amountDue − total, cents-rounded, never a bucket sum', () => {
    summaries.forEach((s, i) => {
      const m = gasMoney(s);
      expect(m.delta).toBe(round2(DUE[i] - TOTALS[i]));
      expect(m.delta).toBe(DUE_MINUS_TOTAL[i]);
    });
    // Exactly three periods disagree — the spec's Dec / Jun / Sep.
    expect(summaries.filter((s) => (gasMoney(s).delta ?? 0) !== 0)).toHaveLength(3);
    expect(gasMoney(summaries[0]).delta).toBeCloseTo(13.87, 2);
    expect(gasMoney(summaries[6]).delta).toBeCloseTo(5.3, 2);
    expect(gasMoney(summaries[9]).delta).toBeCloseTo(6.18, 2);
  });

  it('never derives a payable: gasMoney exposes no fourth figure', () => {
    const keys = Object.keys(gasMoney(summaries[0])).sort();
    expect(keys).toEqual(['amountDue', 'delta', 'total']);
  });
});

describe('rates — ¢/m³, display-only (DoD 4)', () => {
  it('three rate lines per period, none of them dollars and none summed', () => {
    summaries.forEach((s) => {
      const rates = gasRates(s);
      expect(rates).toHaveLength(3);
      for (const r of rates) expect(isRateLine(r)).toBe(true);
      // No ¢/kWh shape anywhere on a gas bill.
      expect(rates.every((r) => /m\s*[³3]/i.test(r.note))).toBe(true);
      expect(rates.every((r) => !/kwh/i.test(r.note))).toBe(true);
    });
    // The published P1 supply rate (rates move every period — this one is
    // the figure the UX spec quotes).
    expect(
      gasRates(summaries[0]).find((r) => r.note === 'Gas Supply Rate ¢/m3')?.amount,
    ).toBeCloseTo(20.4037, 4);
  });

  it('rate lines never appear in the charges list', () => {
    for (const s of summaries) {
      const c = gasCharges(s);
      const notes = [...c.visible, ...c.zero].map((i) => i.note);
      expect(notes.some((n) => /¢\s*\//.test(n))).toBe(false);
    }
  });

  it('the promoted money group is exactly Amount Due + Total + difference', () => {
    const c = gasCharges(summaries[0]);
    const promoted = c.visible.filter(
      (i) => /amount due/i.test(i.note) || /total gas charges/i.test(i.note),
    );
    expect(promoted).toHaveLength(0); // promoted rows are never re-listed
  });
});

describe('volume — labeled numbers, never cross-substituted (DoD 3)', () => {
  it('billed = round(unadjusted × 1.0057); reads give their own delta', () => {
    summaries.forEach((s, i) => {
      const v = gasVolume(s);
      expect(v.billed).toBe(BILLED_VOLUME[i]);
      expect(v.unadjusted).toBeCloseTo(UNADJUSTED[i], 3);
      expect(v.reads?.delta).toBe(READ_DELTA[i]);
      // Three labeled numbers can disagree (period 4: 177 billed vs 176 reads).
      expect(v.billed).not.toBe(v.reads?.delta);
    });
  });

  it('reads the feed’s own Previous Usage consumption, and null when the line is absent', () => {
    // Both committed Enbridge documents state this line in every period — as 0.
    // The card prints it as reported (a line the file carries must be checkable
    // on the page), never as this period's volume, and never invents a figure
    // for a document that does not state one.
    expect(summaries.map((s) => gasVolume(s).previousUsage)).toEqual(Array(10).fill(0));
    const without = {
      ...summaries[0],
      items: summaries[0].items.filter((i) => i.note !== 'Previous Usage consumption'),
    };
    expect(gasVolume(without).previousUsage).toBeNull();
  });
});

describe('interval states A/B/C — absence is a state, never 0 m³ (DoD 3/5)', () => {
  it('periods 1–4 present, period 5 the 1-day stub, periods 6–10 absent', () => {
    const states = summaries.map(gasIntervalState);
    expect(states).toEqual([
      'present', 'present', 'present', 'present', 'stub',
      'absent', 'absent', 'absent', 'absent', 'absent',
    ]);
  });

  it('present blocks carry the published m³; the stub is never a monthly reading', () => {
    const stored = (s: (typeof summaries)[number]) =>
      (s as { _gasInterval?: { m3: number; duration_s: number } })._gasInterval;
    const present = summaries.filter((s) => gasIntervalState(s) === 'present');
    expect(present.map((s) => stored(s)?.m3)).toEqual(BLOCK_VALUES.slice(0, 4));
    const stub = summaries[4];
    expect(gasIntervalState(stub)).toBe('stub');
    // The stub's 1-day window holds 2 m³ — not 112 (its meter read) and not 0.
    expect(stored(stub)?.m3).toBe(BLOCK_VALUES[4]);
    expect(stored(stub)?.duration_s).toBe(86400);
    // An absent period carries no interval object at all — nothing to render
    // as a number, so no code path can paint 0 m³ for it.
    expect((summaries[5] as { _gasInterval?: unknown })._gasInterval).toBeUndefined();
    expect(gasVolume(summaries[5]).billed).toBe(BILLED_VOLUME[5]); // billed ≠ interval
  });

  it('the stored block timestamps sit where the file put them', () => {
    const iso = (s: number) => new Date(s * 1000).toISOString().slice(0, 10);
    const stored = summaries
      .map((s) => (s as { _gasInterval?: { timestamp: number } })._gasInterval)
      .filter((x): x is { timestamp: number } => Boolean(x));
    expect(stored.map((x) => iso(x.timestamp))).toEqual([
      '2025-12-25', '2026-01-27', '2026-02-26', '2026-03-26', '2026-04-27',
    ]);
  });
});

describe('charges list — listed, never summed (DoD 6)', () => {
  it('P1 shows 6 nonzero + the 3 balance lines and collapses 12 zeros', () => {
    const c = gasCharges(summaries[0]);
    expect(c.visible).toHaveLength(9);
    expect(c.zero).toHaveLength(12);
    const balanceNotes = c.visible
      .map((i) => i.note.trim().toLowerCase())
      .filter((n) => /previous balance|payments received|balance forward/.test(n));
    // The zero balance rows are the banner's evidence — they stay visible.
    expect(balanceNotes).toHaveLength(3);
    expect(c.visible.filter((i) => i.amount === 0)).toHaveLength(3);
    expect(c.zero.every((i) => i.amount === 0)).toBe(true);
  });

  it('the whole partition adds up: visible + zero = every non-promoted, non-rate line', () => {
    for (const s of summaries) {
      const c = gasCharges(s);
      const promoted = (i: BillLineItem) =>
        /amount due/i.test(i.note) || /total gas charges/i.test(i.note);
      const moneyLines = s.items.filter(
        (i) => i.amount !== null && !promoted(i) && !isRateLine(i),
      );
      expect(c.visible.length + c.zero.length).toBe(moneyLines.length);
    }
  });
});

describe('bill facts — the file\'s own numbers, as reported (DoD 5)', () => {
  it('P1: bill/due dates, the feed\'s 33-day line, adjustment and pressure', () => {
    const f = gasFacts(summaries[0]);
    expect(f.billDate).not.toBeNull();
    expect(f.dueDate).not.toBeNull();
    expect(f.readStart).not.toBeNull();
    expect(f.readEnd).not.toBeNull();
    expect(f.days?.measurement?.scaled).toBe(33); // one MORE than the 32-day period
    expect(f.adjustment?.measurement?.scaled).toBeCloseTo(1.0057, 4);
    expect(f.pressure?.measurement?.scaled).toBe(0); // reported, never applied
  });
});

describe('recognition does not misfire on electricity', () => {
  it('the Oakville-shaped synthetic export is not gas', () => {
    const oakville = readFileSync(
      join(__dirname, '../../tests/fixtures/usage-summary-synthetic.xml'),
      'utf8',
    );
    const electric = parseGreenButtonFeed(oakville);
    expect(isGasFeed(electric.summaries)).toBe(false);
    expect(electric.summaries.every((s) => !isGasSummary(s))).toBe(true);
    // Enrichment passes electric summaries through untouched (same objects).
    const out = enrichGasSummaries(electric);
    expect(out).toHaveLength(electric.summaries.length);
    expect(out.every((s) => (s as { _gasInterval?: unknown })._gasInterval === undefined)).toBe(
      true,
    );
  });
});

/* ==========================================================================
 * Legacy stored summaries — the shape localStorage held BEFORE the gas wave
 * ========================================================================== */

/**
 * `volume` was added to UsageSummary by the Enbridge wave. Every summary
 * stored earlier — and both e2e seeds (`tests/e2e/mark-seed.ts`,
 * `tests/e2e/plan-switch-fixture.ts`) — has NO `volume` key at all:
 * `summary.volume` is `undefined`, `undefined !== null` is `true`, and
 * `undefined.uom` threw inside `summaries.some(isGasSummary)` →
 * AppErrorBoundary crash ERR-4887C2 on every pre-wave dashboard.
 *
 * The parser always writes `volume`, so every fixture-derived summary in
 * this file has it; these tests construct the stored-legacy shape by hand
 * (delete the key) and pin the recognition path against it.
 */
const stripVolume = (s: UsageSummary): UsageSummary => {
  const legacy: Record<string, unknown> = { ...s };
  delete legacy.volume;
  return legacy as unknown as UsageSummary; // the lie storage tells the type
};

describe('legacy stored summaries — no `volume` key (ERR-4887C2)', () => {
  const oakville = parseGreenButtonFeed(
    readFileSync(join(__dirname, '../../tests/fixtures/usage-summary-synthetic.xml'), 'utf8'),
  );
  const legacyElectric = oakville.summaries.map(stripVolume);
  const legacyGas = summaries.map(stripVolume);

  it('really is the key-less shape (or these tests prove nothing)', () => {
    expect(oakville.summaries.length).toBeGreaterThan(0);
    expect(summaries.length).toBeGreaterThan(0);
    expect('volume' in legacyElectric[0]).toBe(false);
    expect('volume' in legacyGas[0]).toBe(false);
    expect('volume' in summaries[0]).toBe(true); // the parser's own shape
  });

  it('a stored electric summary with no `volume` key is not gas and never throws', () => {
    expect(() => legacyElectric.forEach(isGasSummary)).not.toThrow();
    expect(legacyElectric.every((s) => !isGasSummary(s))).toBe(true);
    expect(isGasFeed(legacyElectric)).toBe(false);
  });

  it('the gas note markers still recognise a stored summary that lacks `volume`', () => {
    expect(legacyGas.every(isGasSummary)).toBe(true);
    expect(isGasFeed(legacyGas)).toBe(true);
  });

  it('a stored feed straddling the wave survives `Array.some` both ways round', () => {
    // The exact crash site: .some() over summaries where the first element
    // has no `volume` key (electric, pre-wave) and the rest are gas.
    expect(isGasFeed([legacyElectric[0], ...legacyGas])).toBe(true);
    expect(isGasFeed([...legacyGas, legacyElectric[0]])).toBe(true);
  });

  it('an absent volume reports null, never 0 — absence is a state', () => {
    expect(gasVolume(legacyGas[0]).billed).toBeNull();
  });
});
